# frozen_string_literal: true
require './config/environment'
Dir[Rails.root.join('spec/fabricators/**/*.rb')].sort.each { |f| load f }
Sidekiq::Testing.fake!
Chewy.strategy(:bypass)

def inside_rollback
  ActiveRecord::Base.transaction do
    yield
    raise ActiveRecord::Rollback
  end
end

def bench(label, n = 40, &blk)
  t = []
  (n + 1).times do |i|
    inside_rollback do
      t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      blk.call
      t << Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0
    end
  end
  t.shift # drop definition-loading call
  puts format('%-46s %7.2fms avg  %7.2fms min  %7.2fms max', label, t.sum / t.size * 1000, t.min * 1000, t.max * 1000)
rescue StandardError => e
  puts format('%-46s FAILED %s: %s', label, e.class, e.message[0, 80])
end

